module radix2_div (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output reg [15:0] result
);

    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg [7:0] sr;
    reg [3:0] cnt;
    reg [3:0] start_cnt;
    reg [7:0] neg_divisor;
    reg [7:0] temp;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            res_valid <= 0;
            sr <= 0;
            cnt <= 0;
            start_cnt <= 0;
            neg_divisor <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                abs_dividend <= (sign && dividend[7]) ? ~dividend + 1 : dividend;
                abs_divisor <= (sign && divisor[7]) ? ~divisor + 1 : divisor;
                sr <= {abs_dividend, 1'b0};
                neg_divisor <= ~abs_divisor + 1;
                cnt <= 4'd0;
                start_cnt <= 4'd1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 4'd8) begin
                    cnt <= 4'd0;
                    start_cnt <= 4'd0;
                    result <= {sr[7:0], sr[15:8]};
                end else begin
                    cnt <= cnt + 4'd1;
                    temp <= sr - neg_divisor;
                    if (temp[8]) begin
                        sr <= {temp[7:0], 1'b0};
                    end else begin
                        sr <= {temp[7:0], 1'b1};
                    end
                end
            end
        end
    end

endmodule
